public class OrderApp {
    static class Inventory {
        int stock = 2;

        void reserve(String sku, int qty) {
            if (qty > stock) {
                throw new IllegalStateException("库存不足: 商品 " + sku + " 剩余 " + stock + ", 需要 " + qty);
            }
            stock -= qty;
        }
    }

    static void placeOrder(Inventory inv, String sku, int qty) {
        try {
            inv.reserve(sku, qty);
        } catch (IllegalStateException e) {
            throw new RuntimeException("Order failed", e);
        }
    }

    public static void main(String[] args) {
        Inventory inv = new Inventory();
        try {
            placeOrder(inv, "A102", 5);
        } catch (RuntimeException e) {
            System.out.println("下单失败: " + e.getCause().getMessage());
        }
    }
}
